-- Communication, part 2: school diary, parent conversations, chatbot, photo gallery, chat moderation.
CREATE TABLE public.comm_diary_templates (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, name VARCHAR(80) NOT NULL, body VARCHAR(300) NOT NULL, UNIQUE (institution_id, name));
CREATE TABLE public.comm_diary (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, class_label VARCHAR(40) NOT NULL, kind VARCHAR(14) NOT NULL CHECK (kind IN ('Class diary', 'Teacher remark')), entry VARCHAR(500) NOT NULL, by_name VARCHAR(80) NOT NULL, diary_date DATE NOT NULL DEFAULT CURRENT_DATE, status VARCHAR(14) NOT NULL DEFAULT 'Sent' CHECK (status IN ('Sent', 'Acknowledged')), template_id UUID REFERENCES public.comm_diary_templates(id) ON DELETE SET NULL);
CREATE TABLE public.comm_conversations (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, parent_name VARCHAR(80) NOT NULL, student_name VARCHAR(80) NOT NULL, teacher_name VARCHAR(80) NOT NULL, last_message VARCHAR(500) NOT NULL, kind VARCHAR(14) NOT NULL CHECK (kind IN ('Parent message', 'Teacher reply')), status VARCHAR(8) NOT NULL DEFAULT 'Unread' CHECK (status IN ('Unread', 'Replied', 'Closed')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.chatbot_conversations (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, channel VARCHAR(10) NOT NULL CHECK (channel IN ('WhatsApp', 'Website')), who VARCHAR(120) NOT NULL, preview VARCHAR(300) NOT NULL DEFAULT '', messages INTEGER NOT NULL DEFAULT 1, outcome VARCHAR(80) NOT NULL DEFAULT 'Answered', rating VARCHAR(12) CHECK (rating IN ('Helpful', 'Not helpful')), topic VARCHAR(40) NOT NULL DEFAULT '', language VARCHAR(12) NOT NULL DEFAULT 'English', handed_to VARCHAR(40), enquiry BOOLEAN NOT NULL DEFAULT false, reply_seconds INTEGER, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.chatbot_unanswered (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, question VARCHAR(300) NOT NULL, times_asked INTEGER NOT NULL DEFAULT 1, channel VARCHAR(10) NOT NULL CHECK (channel IN ('WhatsApp', 'Website')), sent_to VARCHAR(40) NOT NULL DEFAULT 'Front office', answered BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.chatbot_faqs (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, topic VARCHAR(40) NOT NULL, question VARCHAR(300) NOT NULL, answer VARCHAR(1000) NOT NULL DEFAULT '', enabled BOOLEAN NOT NULL DEFAULT false, used INTEGER NOT NULL DEFAULT 0, UNIQUE (institution_id, question));
CREATE TABLE public.gallery_albums (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, title VARCHAR(160) NOT NULL, event VARCHAR(40) NOT NULL, album_date DATE NOT NULL, audience VARCHAR(40) NOT NULL DEFAULT 'Whole school', photo_count INTEGER NOT NULL DEFAULT 0, caption VARCHAR(200) NOT NULL DEFAULT '', blur_no_consent BOOLEAN NOT NULL DEFAULT true, allow_download BOOLEAN NOT NULL DEFAULT true, notify_parents BOOLEAN NOT NULL DEFAULT true, uploaded_by VARCHAR(80) NOT NULL DEFAULT '', status VARCHAR(16) NOT NULL DEFAULT 'Published' CHECK (status IN ('Pending approval', 'Published', 'Sent back')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.gallery_consent (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, student_id UUID REFERENCES public.students(id) ON DELETE SET NULL, student_name VARCHAR(80) NOT NULL, class_label VARCHAR(40) NOT NULL DEFAULT '', parent_name VARCHAR(80) NOT NULL DEFAULT '', reason VARCHAR(120) NOT NULL DEFAULT '', recorded_on DATE NOT NULL DEFAULT CURRENT_DATE, status VARCHAR(20) NOT NULL DEFAULT 'Waiting for parent' CHECK (status IN ('Waiting for parent', 'Received')));
CREATE SEQUENCE public.chat_report_seq START 12;
CREATE TABLE public.chat_reports (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, code VARCHAR(10) NOT NULL DEFAULT ('RP-' || lpad(nextval('public.chat_report_seq')::text, 2, '0')), chat VARCHAR(80) NOT NULL, reported_by VARCHAR(20) NOT NULL, reason VARCHAR(200) NOT NULL, reported_on DATE NOT NULL DEFAULT CURRENT_DATE, decision VARCHAR(8) NOT NULL DEFAULT 'Open' CHECK (decision IN ('Open', 'Kept', 'Removed')), decision_note VARCHAR(200));
CREATE TABLE public.chat_rules (institution_id UUID PRIMARY KEY REFERENCES public.institutions(id) ON DELETE CASCADE, opens_at VARCHAR(5) NOT NULL DEFAULT '08:00', closes_at VARCHAR(5) NOT NULL DEFAULT '18:00', parents_can_message VARCHAR(40) NOT NULL DEFAULT 'Class teacher and subject teachers', keep_history VARCHAR(20) NOT NULL DEFAULT 'The academic year', blocked_words TEXT NOT NULL DEFAULT '', groups_announcement_only BOOLEAN NOT NULL DEFAULT true, students_groups_only BOOLEAN NOT NULL DEFAULT true, show_read_ticks BOOLEAN NOT NULL DEFAULT true);
ALTER TABLE public.comm_diary_templates ENABLE ROW LEVEL SECURITY; ALTER TABLE public.comm_diary ENABLE ROW LEVEL SECURITY; ALTER TABLE public.comm_conversations ENABLE ROW LEVEL SECURITY; ALTER TABLE public.chatbot_conversations ENABLE ROW LEVEL SECURITY; ALTER TABLE public.chatbot_unanswered ENABLE ROW LEVEL SECURITY; ALTER TABLE public.chatbot_faqs ENABLE ROW LEVEL SECURITY; ALTER TABLE public.gallery_albums ENABLE ROW LEVEL SECURITY; ALTER TABLE public.gallery_consent ENABLE ROW LEVEL SECURITY; ALTER TABLE public.chat_reports ENABLE ROW LEVEL SECURITY; ALTER TABLE public.chat_rules ENABLE ROW LEVEL SECURITY;
